 test('Transfers reject invalid amounts and conserve balances',()=>{for(const amount of [-1,0,1.5,NaN,Infinity,1e13]){const a=C.actor(),b=C.actor();a.balance=100;assert.throws(()=>C.transfer(a,b,amount,'x'));assert.equal(a.balance+b.balance,100);}const a=C.actor(),b=C.actor();a.balance=100;C.transfer(a,b,30,'x','tx');assert.equal(a.balance+b.balance,100);assert.equal(C.transfer(a,b,30,'x','tx'),false);});
 test('Cyberware slot exclusivity, weapon cap and risk tuning work',()=>{const a=C.actor();for(let i=0;i<2;i++)a.inventory.push(C.item({id:'arm'+i,name:'arm',category:'cyberware',slot:'arms',capacity:150}));C.equip(a,'arm0');C.equip(a,'arm1');assert.equal(a.inventory.filter(x=>x.equipped).length,1);assert.ok(C.risk(a)>0);assert.equal(C.risk(a,0),0);for(let i=0;i<4;i++){a.inventory.push(C.item({id:'w'+i,category:'weapons'}));if(i<3)C.equip(a,'w'+i);else assert.throws(()=>C.equip(a,'w'+i));}});
 test('Multi-socket cyberware coexists until the group is full',()=>{const a=C.actor();for(let i=0;i<4;i++)a.inventory.push(C.item({id:'circ'+i,name:'implant'+i,category:'cyberware',slot:'circulatory-system',capacity:10}));for(let i=0;i<3;i++)C.equip(a,'circ'+i);assert.equal(a.inventory.filter(x=>x.equipped).length,3);assert.throws(()=>C.equip(a,'circ3'),/sockets full/);assert.equal(C.load(a),30);});
 test('Legacy implant slugs migrate without removing equipment or changing capacity',()=>{const a=C.actor();a.inventory=[{id:'bio',name:'Biomonitor',category:'cyberware',slot:'biomonitor',capacity:15,equipped:true},{id:'skin',name:'Optical Camo',category:'cyberware',slot:'optical-camo',capacity:12,equipped:true}];C.hydrate(a);assert.equal(a.inventory[0].slot,'circulatory-system');assert.equal(a.inventory[1].slot,'integumentary-system');assert.equal(C.load(a),27);assert.equal(C.item({name:'Gorilla Arms',category:'cyberware'}).slot,'arms');});
